with parsed as (select id, service, host, log_ts, level, latency_ms, context, coalesce(context['trace'], 'direct') as trace_or_default, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, size(context) as num_context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier from app_logs) select case when duration_sec >= 3.5 then 'PREMIUM' else 'STANDARD' end as duration_sec_tier, date_trunc('day', log_ts) as activity_day, min(log_ts) as first_seen, count(distinct trace_or_default) as distinct_trace_or_defaults, count(*) as row_count, approx_percentile(latency_ms, 0.5) as latency_ms_p50, bit_and(latency_ms) as latency_ms_bit_and, min(log_ts) as started_at from parsed group by case when duration_sec >= 3.5 then 'PREMIUM' else 'STANDARD' end, date_trunc('day', log_ts) having latency_ms_bit_and > 1 order by latency_ms_bit_and nulls first;
